from itertools import product
num = Rational(0)
den = Rational(0)
for b in range(1, 6):
    k = 3 if b % 2 == 1 else 2
    for w in product([0, 1], repeat=k):
        pr = Rational(1, 5)*Rational(1, 2**k)
        if sum(w) == 2:
            den += pr
            if b % 2 == 1:
                num += pr
ans = num/den
